import numpy as np
e=np.asarray(df['eps']);T_=np.asarray(df['T']);s=np.asarray(df['sigma'])
L=np.log(e)
Tf={'T-2':T_**-2,'T-1':1/T_,'T0':np.ones_like(T_),'T':T_,'T2':T_**2,'T3':T_**3,'logT':np.log(T_),'sqT':np.sqrt(T_)}
Ef={'1':np.ones_like(e),'L':L,'1/e':1/e,'e':e,'e2':e**2,'L/e':L/e,'sqe':np.sqrt(e),'1/e2':1/e**2,'L2':L**2,'eL':e*L,'L/e2':L/e**2}
F={};
for a in Tf:
    for b in Ef: F[a+'*'+b]=Tf[a]*Ef[b]
names=list(F); M=np.c_[[F[k] for k in names]].T
sel=[];best_all=None
